#ifndef MYMONEY_STORAGE_MIGRATIONS_H_
#define MYMONEY_STORAGE_MIGRATIONS_H_

#include <span>
#include <string_view>

#include "core/error.h"
#include "storage/sqlite/database.h"

namespace mymoney::storage {

// One step of the schema history: storage/migrations/NNNN_name.sql (ADR-0013).
struct MigrationScript {
  int version;            // 1, 2, 3, ... - becomes PRAGMA user_version
  std::string_view name;  // file name, for error messages
  std::string_view sql;
};

// The scripts of storage/migrations/, embedded into the binary at build time
// (generated by cmake/EmbedMigrations.cmake).
[[nodiscard]] std::span<const MigrationScript> EmbeddedMigrationScripts();

// The schema version of the database (0 for a new, empty database).
[[nodiscard]] core::Result<int> SchemaVersion(sqlite::Database& db);

// Applies every script newer than the database's schema version, each in its
// own transaction together with its version update. A database newer than
// the newest script is refused - it was written by a newer app.
// Precondition: `scripts` are sorted, with versions 1, 2, 3, ...
[[nodiscard]] core::Status ApplyMigrations(
    sqlite::Database& db, std::span<const MigrationScript> scripts);

}  // namespace mymoney::storage

#endif  // MYMONEY_STORAGE_MIGRATIONS_H_
